BASE='/KINETONE/'
def aimg(i): return f'{BASE}assets/img/{i:02d}-{MEDIA[i]}.webp'
def pic(i, alt, cl='', loading='lazy'):
 return f'<img class="{cl}" src="{aimg(i)}" alt="{html.escape(alt,quote=True)}" loading="{loading}" decoding="async">'
def link(path):return BASE+path.lstrip('/')
def button(url,label,kind='solid'):
 return f'<a class="cta cta-{kind}" href="{link(url)}"><span>{label}</span><span aria-hidden="true">↗</span></a>'
def eyebrow(text):return f'<span class="eyebrow">{text}</span>'
def sectionlead(index,title,copy=''):
 return f'<div class="section-lead">{eyebrow(index)}<h2 class="display">{title}</h2><p>{copy}</p></div>'
