def shell(title,description,body,page='',theme='ivory'):
 nav=''.join(f'<a href="{link(p)}" class="nav-link {"active" if page==p.split("/")[0] else ""}">{t}</a>' for p,t in NAV)
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f2efe6"><meta name="description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)} — KINETONE"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:image" content="https://pfxamd.github.io/KINETONE/assets/img/01-brand-home-hero.webp"><link rel="icon" type="image/svg+xml" href="{link('assets/favicon.svg')}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Space+Grotesk:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="{link('assets/site.css')}"><script defer src="{link('assets/site.js')}"></script><title>{html.escape(title)} — KINETONE</title></head>
<body class="theme-{theme}" data-page="{page}"><a class="skip" href="#main">Skip to content</a><div class="notice"><span>MADE FOR CURIOUS MINDS</span><span>ORIGINAL SOUND OBJECTS / SERIES 01</span><span>EST. IN IMAGINATION</span></div><header class="site-header"><a class="logo" href="{BASE}" aria-label="KINETONE home">KINE<span class="logo-slot">◢</span>TONE<span class="logo-dot">®</span></a><nav class="desktop-nav" aria-label="Main navigation">{nav}</nav><div class="header-actions"><a class="header-play" href="{link('play/')}">START PLAYING <span>↗</span></a><button class="menu-toggle" type="button" aria-label="Open menu" aria-controls="mobile-nav" aria-expanded="false"><span></span><span></span></button></div></header><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" inert>{nav}<a href="{link('support/')}">Support</a></nav><main id="main">{body}</main><footer class="footer"><div class="footer-top"><div>{eyebrow('IT STARTS WITH A SOUND')}<h2>WHAT WILL<br>YOU <i>MAKE?</i></h2>{button('play/','MAKE SOME NOISE')}</div><div class="footer-side"><p>Three sound objects. Infinite ways to play.</p><div class="footer-links"><a href="{link('instruments/')}">Instruments ↗</a><a href="{link('sessions/')}">Sessions ↗</a><a href="{link('design-story/')}">Design story ↗</a><a href="{link('sound-story/')}">Sound story ↗</a><a href="{link('support/')}">Support ↗</a></div></div></div><div class="footer-bottom"><a class="logo footer-logo" href="{BASE}">KINE<span>◢</span>TONE®</a><span>AN ORIGINAL FICTIONAL PRODUCT WORLD — CONCEPT DEMONSTRATION</span><a href="#main">BACK TO TOP ↑</a></div><div class="footer-credit">Designed &amp; developed by <a href="https://pfxamd.com" target="_blank" rel="noopener noreferrer">pfxamd</a></div></footer></body></html>'''
def write(route,title,description,body,page='',theme='ivory'):
 target=DOCS/route/'index.html' if route else DOCS/'index.html';target.parent.mkdir(parents=True,exist_ok=True)
 target.write_text(shell(title,description,body,page,theme),encoding='utf8')

