write('journal','Journal','Stories about instrument design, sound recording and creative culture.',journal,'journal')

# DESIGN STORY
story=f'''<section class="story-hero">{eyebrow('THE DESIGN STORY / 001')}<h1 class="display">BUILT TO BE<br><em>TOUCHED.</em></h1><p>Things you can feel in your hands change the way you create.</p>{pic(23,'Industrial designer working on a KINETONE prototype','story-hero-image','eager')}</section><section class="story-body"><div>{eyebrow('NOTHING EXTRA / EVERYTHING INTENTIONAL')}</div><div><h2>Design starts with what it feels like to play.</h2><p>Before the enclosure, before the colour, before the first sketch comes a simple question: how could this feel more immediate?</p><p>Our three imaginary instruments each answer it differently. PULSE gives your rhythm room to breathe. FORM keeps melody within reach. LOOP helps you hear possibilities in sounds you'd normally pass by.</p></div></section><section class="story-gallery"><div>{pic(3,'Material and enclosure studies for KINETONE instruments')}</div><div>{pic(27,'Blue synthesizer prototype elements and industrial design plans')}</div></section><section class="story-body story-body-last"><div>{eyebrow('AN OBJECT WITH A POINT OF VIEW')}</div><div><h2>Every detail makes a difference.</h2><p>A button with a little resistance. A dial you can find without looking. A colour that makes you want to reach out. We treat those details as part of the music.</p>{button('instruments/','MEET THE INSTRUMENTS','line')}</div></section>'''
write('design-story','Built to be touched','The fictional industrial design process and philosophy behind KINETONE.',story,'journal')

# SOUND STORY
sound=f'''<section class="story-hero story-hero-sound">{eyebrow('THE SOUND STORY / 002')}<h1 class="display">LISTEN<br><em>CLOSER.</em></h1><p>The most interesting sounds can be hiding in plain sight.</p>{pic(24,'Outdoor field recording of environmental sound with KINETONE sampler','story-hero-image','eager')}</section><section class="story-body"><div>{eyebrow('THE WORLD IS AN INSTRUMENT')}</div><div><h2>It doesn't have to start with a melody.</h2><p>Maybe it's the rhythm of footsteps. Maybe it's a door closing or the hum of a city before sunrise. Recording changes how you pay attention.</p><p>That's the spirit of LOOP: a small place to catch an unexpected moment, take it apart, and discover something new.</p></div></section><section class="story-gallery"><div>{pic(22,'Musician using LOOP beside a studio window')}</div><div>{pic(28,'Musician exploring and listening to a new electronic composition')}</div></section><section class="story-body story-body-last"><div>{eyebrow('TRY LISTENING DIFFERENTLY')}</div><div><h2>Capture something ordinary.</h2><p>In our browser playground, you can record a tiny sound of your own, import an audio clip or work with a demo sample. Nothing is sent to a server.</p>{button('play/?instrument=loop','OPEN THE SAMPLER','line')}</div></section>'''
write('sound-story','Listen closer','Explore field recording, sampling and creative sound experimentation.',sound,'journal')

# ABOUT
about=f'''<section class="page-hero basic-page-hero">{eyebrow('THE THOUGHT BEHIND THE THING')}<h1 class="display">SOUND IS<br><em>FOR EVERYONE.</em></h1><div class="page-hero-bottom"><p>Tools that invite curiosity. Objects that encourage experiments. A little more play in every day.</p><span>KINETONE / THE IDEA</span></div></section><section class="about-hero-photo">{pic(3,'KINETONE industrial design materials and prototypes','', 'eager')}</section><section class="story-body"><div>{eyebrow('OUR POINT OF VIEW')}</div><div><h2>Start with a small idea. See how far it goes.</h2><p>We imagine electronic instruments that are easy to approach, rewarding to explore, and thoughtful in every detail.</p><p>KINETONE is a fictional brand and a complete digital product concept. Its purpose is to explore what happens when industrial design, interaction and real-time sound come together in one experience.</p></div></section><section class="section about-values"><div>{eyebrow('HOW WE THINK')}<h2 class="display">PLAY IS<br><em>THE POINT.</em></h2></div><div class="value-grid"><article><span>01 ↗</span><h3>Curiosity first.</h3><p>The best tool makes you wonder what happens next.</p></article><article><span>02 ↗</span><h3>Touch matters.</h3><p>Great interfaces can be felt as well as seen.</p></article><article><span>03 ↗</span><h3>Make it yours.</h3><p>Good instruments leave room for unexpected discoveries.</p></article></div></section>'''
write('about','About KINETONE','The fictional KINETONE brand: original electronic music instruments imagined for curious minds.',about,'about')

# SUPPORT
support=f'''<section class="page-hero page-hero-split support-hero"><div>{eyebrow('THE LITTLE DETAILS')}<h1 class="display">HERE TO<br><em>HELP YOU PLAY.</em></h1><p>Start with a question. Find what you need. Then get back to making something good.</p></div><div class="hero-aside-img">{pic(4,'KINETONE PULSE package and included accessories','', 'eager')}</div></section><section class="section support-guide">{sectionlead('QUICK START / K SERIES','GET GOING IN<br><em>THREE STEPS.</em>')}<div class="guide-grid"><article><span>01</span><h3>Pick an instrument.</h3><p>Discover PULSE, FORM or LOOP. Each has its own sound and way of playing.</p></article><article><span>02</span><h3>Explore the controls.</h3><p>Use the product detail pages to get familiar with each instrument's layout.</p></article><article><span>03</span><h3>Make something.</h3><p>Open the browser playground. Headphones are recommended, but curiosity is essential.</p></article></div></section><section class="section faq">{sectionlead('THE ESSENTIALS','A FEW GOOD<br><em>QUESTIONS.</em>')}<div class="faq-list"><details><summary>Can I actually play these instruments?</summary><p>Yes. The Play page includes working browser-based rhythm, synthesis and sampling experiences, powered by the Web Audio API. The physical devices are fictional concepts.</p></details><details><summary>Is KINETONE a real product brand?</summary><p>No. KINETONE, its devices and their technical specifications are original fictional demonstrations. The website does not sell or ship physical products.</p></details><details><summary>Does the sampler send my microphone recordings to a server?</summary><p>No. Recording, importing and audio processing all happen in your browser memory. Nothing is uploaded or stored by this website.</p></details><details><summary>Can I use the site without audio?</summary><p>Yes. All product information and pages are accessible without sound. Audio only starts when you choose to play an instrument.</p></details><details><summary>Why won't my microphone work?</summary><p>Your browser may require permission, a secure connection or a compatible device. The demo sampler and local audio import work without microphone access.</p></details></div></section>'''
write('support','Support','Guides, answers and useful information about the fictional KINETONE instruments and browser playground.',support,'support')

